/** A spoiler-friendly scout for the worlds generated by a seed; never changes simulation state. */
import { generateMap } from '../src/sim/mapgen';
import type { MapSize, MapType, RuinFind } from '../src/sim/types';

const SIZES = ['small', 'medium', 'large'] as const satisfies readonly MapSize[];
const MAPS = ['continental', 'highlands', 'lakes', 'forest', 'plains', 'sea'] as const satisfies readonly MapType[];
const FINDS = ['hoard', 'lore', 'map', 'relic'] as const satisfies readonly RuinFind[];
const MAX_SEED = 0xffffffff;

export interface AtlasOptions {
  from: number;
  count: number;
  size: MapSize;
  map: MapType;
  players: 2 | 3 | 4;
  iron: 'any' | 'yes' | 'no';
  find: 'any' | RuinFind;
  minPosts: number;
  json: boolean;
}

export interface AtlasRow {
  seed: number;
  bogIron: boolean;
  ruins: RuinFind[];
  posts: number;
  relics: number;
  /** Distance in straight-line tiles, not a path or a walk-time estimate. */
  nearestRuin: number | null;
}

export const ATLAS_HELP = `Seed Atlas — scan reproducible worlds (reveals hidden ruin finds)
Usage: npx tsx scripts/seed-atlas.ts [options]
  --from N         First seed, inclusive (default 1)
  --count N        Number of seeds, 1–500 (default 12)
  --size SIZE      small | medium | large (default small)
  --map TYPE       continental | highlands | lakes | forest | plains | sea
  --players N      2 | 3 | 4 (default 2)
  --iron VALUE     any | yes | no (default any)
  --find FIND      any | hoard | lore | map | relic (default any)
  --min-posts N    At least N neutral trading posts (default 0)
  --json           Machine-readable JSON, with settings for sharing
  --help           Show this help
Example: npx tsx scripts/seed-atlas.ts --from 1 --count 40 --map highlands --iron yes --find relic`;

/** Strict flag parsing: reject misspellings instead of quietly scouting the wrong world. */
export function parseAtlasArgs(args: string[]): AtlasOptions {
  const opts: AtlasOptions = { from: 1, count: 12, size: 'small', map: 'continental', players: 2, iron: 'any', find: 'any', minPosts: 0, json: false };
  const numeric = (name: string, value: string, lo: number, hi: number) => {
    const n = Number(value);
    if (!/^\d+$/.test(value) || !Number.isSafeInteger(n) || n < lo || n > hi) throw new Error(`${name} must be a whole number from ${lo} to ${hi}`);
    return n;
  };
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--json') { opts.json = true; continue; }
    const eq = arg.indexOf('=');
    const flag = eq < 0 ? arg : arg.slice(0, eq);
    if (!['--from', '--count', '--size', '--map', '--players', '--iron', '--find', '--min-posts'].includes(flag)) throw new Error(`Unknown option: ${arg}. Try --help.`);
    const value = eq < 0 ? args[++i] : arg.slice(eq + 1);
    if (!value || value.startsWith('--')) throw new Error(`Missing value for ${flag}`);
    switch (flag) {
      case '--from': opts.from = numeric(flag, value, 0, MAX_SEED); break;
      case '--count': opts.count = numeric(flag, value, 1, 500); break;
      case '--players': opts.players = numeric(flag, value, 2, 4) as AtlasOptions['players']; break;
      case '--min-posts': opts.minPosts = numeric(flag, value, 0, 100); break;
      case '--size':
        if (!SIZES.includes(value as MapSize)) throw new Error(`Invalid size: ${value}`);
        opts.size = value as MapSize;
        break;
      case '--map':
        if (!MAPS.includes(value as MapType)) throw new Error(`Invalid map: ${value}`);
        opts.map = value as MapType;
        break;
      case '--iron':
        if (!['any', 'yes', 'no'].includes(value)) throw new Error(`Invalid iron filter: ${value}`);
        opts.iron = value as AtlasOptions['iron'];
        break;
      case '--find':
        if (value !== 'any' && !FINDS.includes(value as RuinFind)) throw new Error(`Invalid ruin find: ${value}`);
        opts.find = value as AtlasOptions['find'];
        break;
    }
  }
  if (opts.from + opts.count - 1 > MAX_SEED) throw new Error('Seed range exceeds 4294967295');
  return opts;
}

/** Read the same map generator that begins a real match, with no AI turns or spoiler changes to play. */
export function scoutSeed(seed: number, options: Pick<AtlasOptions, 'size' | 'map' | 'players'>): AtlasRow {
  const world = generateMap(seed, options.size, options.players, options.map);
  let nearest = Infinity;
  for (const ruin of world.ruins) for (const start of world.starts) {
    const dx = ruin.x - start.x, dy = ruin.y - start.y;
    nearest = Math.min(nearest, Math.sqrt(dx * dx + dy * dy));
  }
  return {
    seed,
    bogIron: world.bogIron,
    ruins: world.ruins.map((r) => r.find),
    posts: world.posts.length,
    relics: world.relics.length,
    nearestRuin: Number.isFinite(nearest) ? Math.round(nearest) : null,
  };
}

export function matchesAtlas(row: AtlasRow, options: Pick<AtlasOptions, 'iron' | 'find' | 'minPosts'>): boolean {
  return (options.iron === 'any' || row.bogIron === (options.iron === 'yes'))
    && (options.find === 'any' || row.ruins.includes(options.find))
    && row.posts >= options.minPosts;
}

export function scanAtlas(options: AtlasOptions): AtlasRow[] {
  const found: AtlasRow[] = [];
  for (let seed = options.from; seed < options.from + options.count; seed++) {
    const row = scoutSeed(seed, options);
    if (matchesAtlas(row, options)) found.push(row);
  }
  return found;
}

export function formatAtlasTable(rows: AtlasRow[], options: AtlasOptions): string {
  const heading = `Seed Atlas: ${rows.length}/${options.count} worlds | ${options.size} ${options.map} | ${options.players} players`;
  const labels = ['Seed', 'Bog iron', 'Ruins (spoilers)', 'Posts', 'Relics', 'Ruin distance*'];
  const data = rows.map((r) => [String(r.seed), r.bogIron ? 'yes' : 'no', r.ruins.join(', ') || '—', String(r.posts), String(r.relics), r.nearestRuin === null ? '—' : String(r.nearestRuin)]);
  const widths = labels.map((s, i) => Math.max(s.length, ...data.map((r) => r[i].length)));
  const format = (cols: string[]) => cols.map((c, i) => c.padEnd(widths[i])).join('  ');
  return [heading, format(labels), format(widths.map((w) => '-'.repeat(w))), ...data.map(format), ...(rows.length ? [] : ['No matching seeds in this range.']), '* Straight-line tiles from the nearest starting town; terrain may require a longer route.'].join('\n');
}
